import{o as s,c as a,a2 as o,j as t,k as d,g as n,a as i}from"./chunks/framework.CNDaxUod.js";const r={class:"au-cta"},l=["href"],v=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"AsyncUp","text":"Async daily standups for Google Chat","tagline":"Open source. Self-hosted. Your data, your keys, your database — no meeting required.","image":{"src":"/logo.svg","alt":"AsyncUp"},"actions":[{"theme":"brand","text":"Get started →","link":"/guide/getting-started"},{"theme":"alt","text":"Setup path","link":"/guide/getting-started#the-setup-path"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/asyncup-dev/asyncup"}]},"features":[{"icon":"💬","title":"One-tap standups","details":"A DM card opens one form — yesterday, today, blockers, plus a private mood with an optional comment. Edit until the deadline; the posted card updates in place."},{"icon":"🧵","title":"Tidy date threads","details":"Every answer lands as one card per person under the day's thread. The wrap-up posts the count and exactly who's missing."},{"icon":"🏖️","title":"Away-aware","details":"Skip today with a one-line reason posted to the thread (and undo), vacation mode, personal weeks and days off, and Google Calendar OOO sync — away people are never nagged or counted as missing."},{"icon":"⚠️","title":"Blockers that follow up","details":"Blockers open from answers and can be worked as items — tag teammates, acknowledge, post updates, resolve — with daily nudges and stale-blocker escalation."},{"icon":"📊","title":"Insights built in","details":"Trend charts (participation, mood, blockers), weekly digests, anonymous team-mood mode, CSV export, polls, and signed outbound webhooks."},{"icon":"👥","title":"Rosters that keep up","details":"A People grid for who's on, who's required and which days each person works — or follow a Google Group so joiners and leavers sync themselves."},{"icon":"🖥️","title":"Consoles with SSO","details":"Workspace admins sign into the console; everyone else gets a personal page. Google sign-in or SAML, SCIM provisioning — all in the MIT core."},{"icon":"🤖","title":"MCP for your own assistants","details":"Claude Code and other MCP clients can read standups, answer or skip, work blockers, and nudge the team — scoped tokens, no model inside AsyncUp."},{"icon":"🪶","title":"Lightweight forever","details":"One ~300 MB container on 1 vCPU / 512 MB. Embedded SQLite by default — or bring your own PostgreSQL with one env var."},{"icon":"🔌","title":"Platform-agnostic core","details":"Google Chat today; Slack and Microsoft Teams adapters are next on the roadmap. MIT licensed, never SaaS."}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}`),c={name:"index.md"},m=Object.assign(c,{setup(p){return(h,e)=>(s(),a("div",null,[e[2]||(e[2]=o('<div class="au-section"><h2>How a morning works</h2><p class="au-sub">No meeting, no interrogation bot — one card, one form, one thread.</p><div class="au-steps"><div class="au-step"><span class="num">1</span><h3>The bot DMs your team</h3><p>At 09:30 in <em>each person&#39;s own timezone</em>, everyone gets a card with a <b>Fill standup</b> button — yesterday pre-filled from their last &quot;today&quot;. One gentle reminder before the deadline.</p></div><div class="au-step"><span class="num">2</span><h3>Answers thread up neatly</h3><p>Each submission posts as a card under the day&#39;s thread in your team space. Re-submit to edit in place. Skips, vacations, and calendar OOO show as away — never as missing.</p></div><div class="au-step"><span class="num">3</span><h3>The wrap-up holds the line</h3><p>At the deadline: who submitted, who didn&#39;t, who&#39;s away and why, open blockers — plus a weekly digest with trends. Moods stay private, in the web app.</p></div></div></div><div class="au-section"><h2>What your team space sees</h2><p class="au-sub">A real thread from a Wednesday.</p><div class="au-thread"><div class="day">📅 Daily Standup — Wed, 11 Jun</div><div class="au-msg"><div class="avatar">😄</div><div class="bubble"><div class="who">Asha</div><div class="q">Yesterday</div> Shipped the payments retry queue <div class="q">Today</div> Start on the invoice exports <div class="q">Blockers</div> ✅ None </div></div><div class="au-msg"><div class="avatar">😐</div><div class="bubble"><div class="who">Rohit <small>· edited</small></div><div class="q">Yesterday</div> Auth refactor review rounds <div class="q">Today</div> Land it, then pick up the flaky e2e <div class="q">Blockers</div><span class="blocked">⚠️ Waiting on staging API keys (2d)</span></div></div><div class="au-wrapup"> 📊 Wrap-up  ·  ✅ 7/8 submitted  ·  ❌ Missing: Dev  ·  🏖️ Away: Mei  ·  ⚠️ 1 open blocker </div></div></div><div class="au-section au-compare"><h2>Why self-host AsyncUp?</h2><p class="au-sub">Hosted standup bots charge per user per month and hold your team&#39;s daily history.</p><table tabindex="0"><thead><tr><th></th><th><strong>AsyncUp</strong></th><th>Hosted standup bots</th></tr></thead><tbody><tr><td>Cost</td><td>$0 forever — MIT licensed</td><td>Per user, per month</td></tr><tr><td>Your standup history</td><td>In <strong>your</strong> SQLite file or Postgres</td><td>On their servers</td></tr><tr><td>AI</td><td>None inside; your own assistants connect over MCP with scoped tokens</td><td>Their model, their terms</td></tr><tr><td>Infrastructure</td><td>One small container, scale-to-zero friendly</td><td>—</td></tr><tr><td>Customization</td><td>Questions, schedules, escalation, the web app — and the source code</td><td>What the plan allows</td></tr></tbody></table></div>',3)),t("div",r,[e[0]||(e[0]=t("h2",null,"Up and running in an afternoon",-1)),t("a",{class:"button",href:d(n)("/guide/getting-started")},"Follow the setup path",8,l),e[1]||(e[1]=t("span",{class:"alt"},[t("code",null,"docker compose up -d"),i(" — amd64 & arm64 images on GHCR")],-1))])]))}});export{v as __pageData,m as default};
